
void band_mixer_tests(const std::filesystem::path& dir){
    auto band=BandDocument::inactive_default();band.assign_gm_patch(0,16);band.load(band.save_bytes());
    const auto before=band.save_bytes();const auto original=band.instruments();
    require(!band_mixer_active(original[0])&&(original[0].flags&1),"Patch assignment does not activate the mixer");
    require(band.set_mix({{0,61,102}}),"Mixer applies screenshot L2/102 to existing PChannel");
    const auto mixed=band.save_bytes();const auto values=band.instruments();
    require(values[0].pan==61&&values[0].volume==102&&values[0].patch==16&&values[0].flags==(original[0].flags|0x60),"Mixer changes only pan volume and their validity");
    require(values[1].flags==original[1].flags&&values[1].pan==original[1].pan&&values[1].volume==original[1].volume,"Mixer preserves other inactive channels");
    require(band.undo()&&band.save_bytes()==before&&!band.dirty()&&!band.can_undo()&&band.can_redo(),"One mixer batch restores exact clean native bytes on Undo");
    for(const auto& invalid:std::vector<std::vector<BandMixValue>>{{},{ {0,128,1} },{{0,1,128}},{{0,1,1},{99,1,1}},{{0,1,1},{0,2,2}},{{0xfffffffcu,1,1}}})
        require(!band.set_mix(invalid)&&band.save_bytes()==before&&!band.dirty()&&!band.can_undo()&&band.can_redo(),"Rejected mixer batch preserves all bytes dirty and existing Redo");
    require(band.redo()&&band.save_bytes()==mixed&&!band.set_mix({{0,61,102}})&&band.can_undo(),"Mixer Redo and unchanged batch retain history");
    band.load(before);require(band.set_mix({{0,0,127},{1,127,0}}),"Mixer supports simultaneous opposite boundary values");
    require(band.instruments()[1].flags==(original[1].flags|0x60)&&!(band.instruments()[1].flags&3),"Activating mixer on gray instrument leaves patch and bank inactive");
    require(band.undo()&&band.save_bytes()==before&&!band.can_undo(),"Multiple PChannels undo as one transaction");
    auto opaque=Chunk::parse(before);auto& item=opaque.find("LIST","lbil")->children[0];auto bins=item.find("bins");bins->data.push_back(0x98);bins->padding=0x73;Chunk unknown;unknown.id="mix?";unknown.data={7,3,1};unknown.padding=0x92;item.children.push_back(unknown);band.load(opaque.encode());
    require(band.set_mix({{0,63,64}}),"Mixer accepts instrument extension bytes");
    const auto kept=Chunk::parse(band.save_bytes());const auto& keptItem=kept.find("LIST","lbil")->children[0];require(keptItem.find("mix?")->encode()==unknown.encode()&&keptItem.find("bins")->data.back()==0x98&&keptItem.find("bins")->padding==0x73,"Mixer preserves opaque chunks extended header and padding");
    require(band.set_collection_reference(0,{L"MixerTone.dls",{}}),"Mixer fixture owns a DLS descriptor");
    auto dlsRoot=Chunk::parse(band.save_bytes());auto dlsDescriptor=dlsRoot.find("LIST","lbil")->children[0].find("LIST","DMRF");dlsDescriptor->children.push_back(unknown);dlsDescriptor->find("refh")->data.push_back(0x39);dlsDescriptor->find("refh")->padding=0x47;band.load(dlsRoot.encode());const auto descriptorBefore=dlsDescriptor->encode();const auto patchBefore=band.instruments()[0].patch;
    require(band.set_mix({{0,32,96}}),"Mixer edits an instrument with an extended DLS descriptor");
    const auto dlsAfter=Chunk::parse(band.save_bytes());require(dlsAfter.find("LIST","lbil")->children[0].find("LIST","DMRF")->encode()==descriptorBefore&&band.instruments()[0].patch==patchBefore,"Mixer retains DLS identity locale opaque descriptor tails and padding");
    require(band.add_gm_instrument(40,0xfffffffbu,64,100),"Mixer fixture includes highest nonreserved DWORD channel");band.load(band.save_bytes());const auto highBefore=band.save_bytes();require(band.set_mix({{0xfffffffbu,17,82}})&&band.instruments().back().pchannel==0xfffffffbu,"Mixer retains high DWORD PChannel without16-channel regression");
    require(band.undo()&&band.save_bytes()==highBefore,"High PChannel edit undoes exactly");
    const BandMixerArea area{100,200,251,349,24,22};BandInstrument point{16,17,0x1163,61,102,{}};
    const auto position=band_mixer_position(point,0,area);const auto value=band_mixer_value(17,position,area);
    require(position.x==161&&position.y==225&&value.pan==61&&value.volume==102,"Grid coordinates implement independent MIDI pan and volume axes");
    const auto upperLeft=band_mixer_value(17,{INT32_MIN,INT32_MIN},area),lowerRight=band_mixer_value(17,{INT32_MAX,INT32_MAX},area);require(upperLeft.pan==0&&upperLeft.volume==127&&lowerRight.pan==127&&lowerRight.volume==0,"Mixer pointer bounds clamp to complete0..127 domain");
    require(band_mixer_pan_label(0)==L"L63"&&band_mixer_pan_label(61)==L"L2"&&band_mixer_pan_label(63)==L"Center"&&band_mixer_pan_label(127)==L"R64","Pan labels follow original CHM L63..R64 scale");
    auto second=point;second.pchannel=0xfffffffbu;second.pan=100;second.volume=60;const auto dragged=band_mixer_drag({point,second},{17,0xfffffffbu},area,4,-7);require(dragged.size()==2&&dragged[0].pan==65&&dragged[0].volume==109&&dragged[1].pan==104&&dragged[1].volume==67,"Grouped drag preserves relative balance across high DWORD channels");
    const auto rollback=band_mixer_explicit_values({point,second},{0xfffffffbu,17});
    require(rollback&&rollback->size()==2&&rollback->front().pchannel==0xfffffffbu&&rollback->front().pan==100&&rollback->back().volume==102,"Preview rollback retains explicit starting mix and selected high DWORD order");
    auto inherited=point;inherited.flags&=~0x20u;
    require(!band_mixer_explicit_values({inherited,second},{17,0xfffffffbu})&&!band_mixer_explicit_values({point},{17,17})&&!band_mixer_explicit_values({point},{18}),"Unknown inherited or duplicate rollback batches cannot pretend to know runtime state");
    auto edited=point;edited.pan=12;edited.volume=40;const auto historyMix=band_mixer_changed_values({point,second},{edited,second});
    require(historyMix.size()==1&&historyMix[0].pchannel==17&&historyMix[0].pan==12&&historyMix[0].volume==40,"History runtime delta includes only changed explicit channel mix");
    require(band_mixer_changed_values({edited},{inherited}).empty(),"Undo to an inherited mix cannot send inactive stored values as authoritative MIDI");
    auto patched=edited;patched.patch=42;auto collected=edited;collected.collectionReference={1,2,3};
    require(band_mixer_changed_values({point},{patched}).empty()&&band_mixer_changed_values({point},{collected}).empty(),"Patch and DLS history changes require snapshot playback rather than partial mixer updates");
    rejected([&]{band_mixer_drag({point},{17,17},area,1,1);},"Duplicate mixer selection is rejected before preview");rejected([&]{band_mixer_drag({point},{18},area,1,1);},"Unknown mixer selection cannot silently create an instrument");
    auto d=SegmentDocument::create_empty({},L"Mixer");d.add_tracks({SegmentTrackKind::band});d.insert_default_band(0);d.insert_default_band(768);d.load(d.save_bytes());const auto file=dir/L"Mixer.sgp";d.save(file.wstring());Framework host;host.open_segment(file.wstring());const auto ownerBefore=host.document(0).save_bytes();auto target=make_embedded_band_target(host,0,1,0,0);auto view=read_embedded_band(host,target);const auto sibling=host.document(0).band_events()[1].band;view->band.set_mix({{0,61,102},{15,100,30}});
    require(update_embedded_band(host,target,view->event.logicalTime,view->event.physicalTime,view->band.save_bytes())&&host.document(0).band_events()[1].band==sibling,"Mixer batch commits to its embedded owner without changing sibling Band");
    require(host.document(0).undo()&&host.document(0).save_bytes()==ownerBefore&&!host.document(0).can_undo()&&host.document(0).redo(),"Embedded mixer creates exactly one Segment Undo/Redo transaction");
    host.save_segment(0,file.wstring());Framework restored;restored.open_segment(file.wstring());require(restored.document(0).save_bytes()==host.document(0).save_bytes()&&!restored.document(0).dirty(),"Mixer flags and multiple values survive independent clean Segment load");
    require(restored.dirty(),"Opening an independently saved Segment marks its new Project membership dirty");
}
void embedded_band_target_tests(const std::filesystem::path& dir){
    auto d=SegmentDocument::create_empty({},L"Band target");d.add_tracks({SegmentTrackKind::band});d.insert_default_band(0);d.insert_default_band(768);
    const auto path=dir/L"EmbeddedBandTarget.sgp";d.save(path.wstring());Framework host;host.open_segment(path.wstring());
    auto target=make_embedded_band_target(host,0,1,0,0);const auto initial=host.document(0).save_bytes();const auto bandCount=host.band_documents().size();
    const auto future=make_embedded_band_target(host,0,1,0,1);
    require(embedded_band_is_playing(initial,target,0)&&embedded_band_is_playing(initial,target,766),"Live mixer binds the initial Band during its actual playback interval");
    require(!embedded_band_is_playing(initial,future,0)&&!embedded_band_is_playing(initial,target,767)&&embedded_band_is_playing(initial,future,767),"Live mixer never applies a future or superseded Band at the current playback clock");
    auto wrongGroup=target;wrongGroup.groups=2;auto wrongTrack=target;wrongTrack.track=1;auto wrongIdentity=target;wrongIdentity.identity[0]^=0x5a;
    require(!embedded_band_is_playing(initial,wrongGroup,0)&&!embedded_band_is_playing(initial,wrongTrack,0)&&!embedded_band_is_playing(initial,wrongIdentity,0),"Live mixer refuses another group track or native Band identity");
    require(!embedded_band_is_playing(initial,target,-1)&&!embedded_band_is_playing(initial,target,host.document(0).length()),"Live mixer refuses clocks outside the playable Segment");
    auto multiple=host.document(0);multiple.select_track_group(2);multiple.add_tracks({SegmentTrackKind::band});multiple.insert_default_band(0);
    require(!embedded_band_is_playing(multiple.save_bytes(),target,0),"Multiple Band tracks remain unqualified for live edits rather than selecting an arbitrary owner");
    auto view=read_embedded_band(host,target);require(view&&view->event.physicalTime==-1&&view->band.instruments().size()==16,"Embedded view resolves the owner event without a standalone Band document");
    const auto first=band_start_position(view->timeline,-1),second=band_start_position(view->timeline,767);
    require(first.measure==0&&first.beat==0&&first.tick==-1&&second.measure==0&&second.beat==1&&second.tick==-1,"Band signed start fields display preceding ticks on their intended beat");
    require(band_start_clocks(view->timeline,first)==-1&&band_start_clocks(view->timeline,second)==767,"Signed Band time representation round-trips without changing global Timeline");
    rejected([&]{view->timeline.clocks({0,0,-1});},"Global Timeline continues to reject negative ticks");
    require(!update_embedded_band(host,target,0,-1,view->event.band)&&host.document(0).save_bytes()==initial&&!host.document(0).can_undo(),"Unchanged embedded property edit leaves owner history clean");
    view->band.set_name(L"Embedded target");
    require(update_embedded_band(host,target,1536,1535,view->band.save_bytes())&&target.event==1,"Owned property edit resolves reordered native event index");
    require(host.band_documents().size()==bandCount&&host.document(0).can_undo(),"Embedded edits create only Segment history and no independent Band document");
    require(read_embedded_band(host,target)->band.name()==L"Embedded target"&&host.document(0).band_events()[0].logicalTime==768,"Editing one embedded view preserves the other Band");
    require(host.document(0).undo()&&host.document(0).save_bytes()==initial,"Combined embedded name and timing change undoes atomically");
    require(read_embedded_band(host,target)&&read_embedded_band(host,target)->target.event==0&&read_embedded_band(host,target)->event.logicalTime==0,"An open target follows its unique identity after Undo reorders events");
    require(host.document(0).redo()&&read_embedded_band(host,target)->event.logicalTime==1536,"An open target follows the same native identity through Redo");
    const auto stable=host.document(0).save_bytes();auto other=make_embedded_band_target(host,0,1,0,0);
    require(!update_embedded_band(host,target,768,767,read_embedded_band(host,target)->event.band)&&host.document(0).save_bytes()==stable,"Duplicate logical target cannot overwrite a different embedded Band");
    host.document(0).select_track_group(2);host.document(0).add_tracks({SegmentTrackKind::band});host.document(0).insert_default_band(0);
    view=read_embedded_band(host,target);view->band.set_name(L"Group one");
    require(update_embedded_band(host,target,1536,1535,view->band.save_bytes())&&host.document(0).selected_groups()==2,"Embedded target commits its own group and restores the active owner selection");
    require(host.document(0).band_events()[0].logicalTime==0&&host.document(0).band_events()[0].band!=view->band.save_bytes(),"Embedded edit does not alias an inactive group's similarly indexed event");
    host.document(0).select_track_group(1);host.document(0).delete_band(target.event);
    require(!read_embedded_band(host,target)&&read_embedded_band(host,other),"Deleted embedded target becomes unavailable without selecting its surviving sibling");
    require(host.document(0).undo()&&read_embedded_band(host,target),"Undo restores an unavailable view through native identity");
    const auto copy=read_embedded_band(host,target)->event.band;host.document(0).set_band(2304,copy);
    auto ambiguous=target;ambiguous.logical=3072;
    require(!read_embedded_band(host,ambiguous),"Ambiguous copied native identities never guess an event by array index");
    require(read_embedded_band(host,target)&&read_embedded_band(host,target)->event.logicalTime==1536,"Exact logical identity still selects a copied Band independently");
    auto invalid=target;invalid.document=99;
    require(!read_embedded_band(host,invalid)&&!update_embedded_band(host,invalid,0,-1,copy),"Stale owner indexes disable embedded reads and writes");
}
void segment_band_owner_tests(const std::filesystem::path& dir){
    band_mixer_tests(dir);
    embedded_band_target_tests(dir);
    using K=SegmentTrackKind;
    const auto factory=BandDocument::inactive_default(L"Band1");const auto inactive=factory.instruments();
    require(inactive.size()==16&&!factory.dirty()&&!factory.can_undo(),"Default UI Band owns16 inactive PChannels at clean checkpoint");
    for(size_t i=0;i<inactive.size();++i){require(inactive[i].pchannel==i&&(inactive[i].flags&0x28fbu)==0,"Default Band settings remain inactive without limiting channel domain");require(inactive[i].patch==(i==9?0x80000000u:0u),"Only default PChannel10 uses standard percussion patch");}
    require(Chunk::parse(factory.save_bytes()).find("guid")->data!=Chunk::parse(BandDocument::inactive_default().save_bytes()).find("guid")->data,"Default Band copies have independent identities");
    auto d=SegmentDocument::create_empty({},L"Band owner");const auto noTrack=d.save_bytes();size_t at=99;
    require(!d.insert_default_band(0,&at)&&at==99&&d.save_bytes()==noTrack&&!d.can_undo(),"Insert does not silently invent missing selected Band track");
    d.add_tracks({K::band});d.load(d.save_bytes());const auto before=d.save_bytes();
    require(!d.insert_default_band(-1)&&!d.insert_default_band(1)&&!d.insert_default_band(d.length())&&d.save_bytes()==before&&!d.can_undo(),"Insert accepts only an existing beat inside Segment");
    require(d.insert_default_band(0,&at)&&at==0&&d.band_events().size()==1,"First beat Insert creates one explicitly owned event");
    require(d.band_events()[0].logicalTime==0&&d.band_events()[0].physicalTime==-1,"Inserted primary Band belongs to beat0 and starts at minus1tick");
    BandDocument first;first.load(d.band_events()[0].band);require(first.name()==L"Band1"&&first.instruments().size()==16,"Inserted payload retains default inactive instrument rows");
    const auto firstBytes=d.save_bytes();require(d.undo()&&d.save_bytes()==before&&!d.dirty()&&d.redo()&&d.save_bytes()==firstBytes,"Insert is one owner Undo/Redo transaction with clean checkpoint restoration");
    require(!d.insert_default_band(0)&&d.save_bytes()==firstBytes,"Occupied beat Insert does not overwrite existing Band");
    require(d.insert_default_band(768,&at)&&at==1&&d.band_events()[1].physicalTime==767,"Second beat Insert has independent preroll timing");
    BandDocument second;second.load(d.band_events()[1].band);require(second.name()==L"Band2"&&Chunk::parse(first.save_bytes()).find("guid")->data!=Chunk::parse(second.save_bytes()).find("guid")->data,"Multiple markers have separate display names and native identities");
    const auto two=d.save_bytes();first.set_name(L"変更 Band");
    require(d.update_band(0,1536,1535,first.save_bytes(),&at)&&at==1,"Name and two time fields update and return reordered explicit index");
    require(d.band_events()[0].band==second.save_bytes()&&d.band_events()[1].band==first.save_bytes(),"Updating one embedded Band preserves the other copy");
    const auto edit=d.save_bytes();require(d.undo()&&d.save_bytes()==two&&d.redo()&&d.save_bytes()==edit,"Combined name/timing change is one Segment transaction");
    require(d.undo(),"Prepare retained Redo before invalid embedded Band edits");
    const auto stable=d.save_bytes();at=77;
    require(!d.update_band(8,0,-1,first.save_bytes(),&at)&&!d.update_band(0,-1,0,first.save_bytes())&&!d.update_band(0,d.length(),0,first.save_bytes())&&!d.update_band(0,0,d.length(),first.save_bytes())&&!d.update_band(0,768,767,first.save_bytes()),"Invalid index, bounds and ambiguous logical target are rejected");
    rejected([&]{d.update_band(0,0,-1,Bytes{1,2,3});},"Malformed edited Band rejected before owner mutation");
    require(d.save_bytes()==stable&&d.can_redo()&&at==77,"Rejected updates retain bytes dirty history and result index");
    BandDocument original;original.load(d.band_events()[0].band);require(!d.update_band(0,0,-1,original.save_bytes())&&d.save_bytes()==stable&&d.can_redo(),"Unchanged embedded edit retains Redo");
    auto root=Chunk::parse(stable);Chunk* track=nullptr;for(auto& t:root.find("LIST","trkl")->children)if(is_band_track(t))track=&t;
    auto& items=track->find("RIFF","DMBT")->find("LIST","lbdl")->children;auto header=items[0].find("bd2h");header->data.push_back(0xa5);header->padding=0xc7;
    Chunk opaque;opaque.id="zzzz";opaque.data={3,1,4};opaque.padding=0x95;const auto opaqueBytes=opaque.encode();items[0].children.push_back(opaque);items.insert(items.begin()+1,opaque);d.load(root.encode());
    require(d.update_band(0,1536,1535,first.save_bytes(),&at)&&at==1,"Indexed update supports extended Band header and opaque siblings");
    const auto changed=Chunk::parse(d.save_bytes());const Chunk* changedTrack=nullptr;for(const auto& t:changed.find("LIST","trkl")->children)if(is_band_track(t))changedTrack=&t;
    const auto& retained=changedTrack->find("RIFF","DMBT")->find("LIST","lbdl")->children;const auto tail=retained[2].find("bd2h");
    require(retained[1].encode()==opaqueBytes&&retained[2].find("zzzz")->encode()==opaqueBytes&&tail->data.size()==9&&tail->data[8]==0xa5&&tail->padding==0xc7,"Owner edit preserves unknown slots header tails and padding through sorting");
    d.select_track_group(2);d.add_tracks({K::band});require(d.insert_default_band(0)&&d.band_events().size()==1,"Insertion targets selected group2 native track");
    BandDocument high;high.load(d.band_events()[0].band);require(high.add_gm_instrument(40,0xfffffffbu,127,0)&&d.update_band(0,0,-1,high.save_bytes()),"Embedded editor retains valid high DWORD PChannel outside default16 rows");
    const auto grouped=d.save_bytes();d.select_track_group(1);require(d.band_events().size()==2&&d.band_events()[1].band==first.save_bytes(),"Other group update cannot alias group1 Band events");
    const auto base=dir/L"BandOwner";std::filesystem::create_directories(base);d.save((base/L"Owned.sgp").wstring());Framework host;host.open_segment((base/L"Owned.sgp").wstring());host.save_project((base/L"BandOwner.pro").wstring());Framework restored;restored.open_project((base/L"BandOwner.pro").wstring());
    require(restored.document(0).save_bytes()==grouped&&!restored.dirty()&&!restored.document(0).can_undo(),"Embedded Band timing identity inactive flags and unknown data survive native Project reload");
    restored.document(0).select_track_group(2);BandDocument reloaded;reloaded.load(restored.document(0).band_events()[0].band);require(reloaded.instruments().back().pchannel==0xfffffffbu,"Native reload preserves high DWORD PChannel outside16-row default");
    auto legacy=root;Chunk* legacyTrack=nullptr;for(auto& t:legacy.find("LIST","trkl")->children)if(is_band_track(t))legacyTrack=&t;auto old=legacyTrack->find("RIFF","DMBT")->find("LIST","lbdl")->children[0].find("bd2h");old->id="bdih";old->data.erase(old->data.begin()+4,old->data.begin()+8);d.load(legacy.encode());
    require(d.update_band(0,0,-1,first.save_bytes()),"Legacy bdih copy converts only when physical time differs");
    const auto converted=Chunk::parse(d.save_bytes());const Chunk* convertedTrack=nullptr;for(const auto& t:converted.find("LIST","trkl")->children)if(is_band_track(t))convertedTrack=&t;const auto resultHeader=convertedTrack->find("RIFF","DMBT")->find("LIST","lbdl")->children[0].find("bd2h");
    require(resultHeader&&resultHeader->data.size()==9&&resultHeader->data[8]==0xa5&&resultHeader->padding==0xc7,"Legacy header conversion preserves opaque tail and pad on atomic owner edit");
}
